#define ll long long

const int B = 100, MAX = 2e5 + B + 5;

int n, q, offset, numBlocks; ll A[MAX], val[MAX], cut[MAX];

void buildBlock(int blk){
    int l = blk * B;
    int r = l + B - 1;

    ll cur = 0;

    for (int i = l; i <= r; i++)
        cur = floor(sqrtl((long double)cur + A[i]));

    val[blk] = cur;

    ll req = cur + 1;

    for (int i = r; i >= l; i--){
        if (req > 2e9){
            cut[blk] = 2e18;
            return;
        }
        req = req * req - A[i];
    }
    cut[blk] = req;
}
ll qry(){
    ll cur = 0;

    for (int b = 0; b < numBlocks; b++)
        cur = (cur >= cut[b]) ? val[b] + 1 : val[b];

    return cur;
}

int main(){
    ios_base::sync_with_stdio(0); cin.tie(0); 
    cin >> n >> q;

    offset = (B - n % B) % B;
    n += offset;
    numBlocks = n / B;

    for (int i = offset; i < n; i++)
        cin >> A[i];

    for (int b = 0; b < numBlocks; b++)
        buildBlock(b);

    while (q--){
        ll k, x;
        cin >> k >> x;
        k--; 
        k += offset;

        A[k] = x;
        buildBlock(k / B);

        cout << qry() << "\n";
    }
}

