void dfs2(int x, int p){
    chain[head[x]].pb(x);
    par[x] = p;
    weight[x] = 1;
    in[x] = tim++;
    for(int i : g[x]){
        head[i] = (i == g[x][0] ? head[x] : i);
        dfs2(i, x);
        if(i != g[x][0]) weight[x] += sub[i];
    }
    out[x] = tim - 1;
