        dfs1(1);
        head[1] = 1;
        dfs2(1, 1);
        dfs3(1);
        for(int i = 1; i <= n; i++){
            if(chain[i].size()){
                int p = dnq(0, chain[i].size() - 1, -1, chain[i]);
                for(int j : chain[i]) rt[j] = p;
            }
        }
        for(int i = 1; i <= n; i++){
            deg1[i].insert(LLINF);
            deg2[i].insert(LLINF);
            for(int j : g[i]){
                if(head[j] == head[i]) continue;
                deg1[i].insert(max((ll)0, dp0[j][1] - dp0[j][0]));
                deg2[i].insert(max((ll)0, min(dp0[j][1], dp0[j][2]) - dp0[j][0]));
                sum012[i] += min({dp0[j][0], dp0[j][1], dp0[j][2]});
                sum01[i] += min(dp0[j][0], dp0[j][1]);
                sum0[i] += dp0[j][0];
                sum2[i] += dp0[j][2];
            }
            rebuild(i);
            pull(i);
        } 
        while(q--){
            int t, x, v;
            cin >> t >> x >> v;
            rem(x);
            if(t == 1) a[x] += v;
            else c[x] += v, sum += v;
            rebuild(x);
            pull(x);
            add(x);
            cout << (min({eval(1, 0), eval(1, 1), eval(1, 2)}) == sum ? "YES" : "NO") << "\n";
        }
        tim = 0;
        for(int i = 1; i <= n; i++){
            a[i] = b[i] = c[i] = 0;
            g[i].clear();
            chain[i].clear();
            deg1[i].clear();
            deg2[i].clear();
            sum0[i] = sum2[i] = sum01[i] = sum012[i] = 0;
        }
    }
}

